// fx-CG50 walkthrough check.
// 1. Arithmetic screens: the displayed result is recomputed exactly from the typed entry,
//    and the key sequence must spell that entry.
// 2. Distribution guides: generated by the app's own prepareGuide(), then checked for
//    the menu route and field order recorded in the fx-CG50 Skill Finder master cards
//    (cards binomial-probability, normal-probability, inverse-normal), and for a result
//    that matches an independent computation.
// This is tool verification only. It is not physical-calculator verification.
import { readFileSync } from 'node:fs';
import { prepareGuide } from '../src/app/calculator.js';
import { Q, Phi, invPhi, binom } from './lib/stats.mjs';

// ---------- expression evaluator for typed entries ----------
// Exact rationals by default; floating point only when an exponent is not a whole number.
const exactOps = { lit: t => Q.of(t), add: (a, b) => a.add(b), sub: (a, b) => a.sub(b), mul: (a, b) => a.mul(b), div: (a, b) => a.div(b),
  pow: (a, b) => { if (b.d !== 1n) throw new RangeError('fractional exponent'); let r = Q.of(1); for (let k = 0n; k < b.n; k += 1n) r = r.mul(a); return r; } };
const floatOps = { lit: Number, add: (a, b) => a + b, sub: (a, b) => a - b, mul: (a, b) => a * b, div: (a, b) => a / b, pow: (a, b) => a ** b };
function parse(entry, ops) {
  const tokens = entry.replace(/[−]/g, '-').replace(/×/g, '*').replace(/÷/g, '/').match(/\d+\.?\d*|\.\d+|[-+*/^()]/g);
  let i = 0;
  const peek = () => tokens[i];
  const primary = () => {
    const t = tokens[i++];
    if (t === '(') { const v = additive(); i += 1; return v; }
    if (t === '-') return ops.sub(ops.lit('0'), power());
    return ops.lit(t);
  };
  const power = () => { const base = primary(); if (peek() === '^') { i += 1; return ops.pow(base, power()); } return base; };
  const term = () => { let v = power(); while (peek() === '*' || peek() === '/') v = tokens[i++] === '*' ? ops.mul(v, power()) : ops.div(v, power()); return v; };
  const additive = () => { let v = term(); while (peek() === '+' || peek() === '-') v = tokens[i++] === '+' ? ops.add(v, term()) : ops.sub(v, term()); return v; };
  const value = additive();
  if (i !== tokens.length) throw new Error(`could not parse ${entry}`);
  return value;
}
const evaluate = entry => { try { return parse(entry, exactOps); } catch (error) { if (error instanceof RangeError) return parse(entry, floatOps); throw error; } };
const isExact = value => value instanceof Q;

const keyFor = { '.': 'DOT', '/': 'DIV', '*': 'MUL', '+': 'ADD', '-': 'SUB', '(': 'LP', ')': 'RP', '^': 'POW' };
const spell = entry => ['AC', ...[...entry.replace(/\s/g, '')].map(c => /\d/.test(c) ? c : keyFor[c]), 'EXE'];
const significant = text => text.replace(/^[−-]?0*\.?0*/, '').replace(/\./, '').length;

// ---------- routes from the Skill Finder master cards ----------
const routes = {
  'Binomial PD': { keys: ['MENU', '2', 'F5', 'F5', 'F1'], fields: ['x', 'Numtrial', 'p'] },
  'Binomial CD': { keys: ['MENU', '2', 'F5', 'F5', 'F2'], fields: ['Lower', 'Upper', 'Numtrial', 'p'] },
  'Normal CD': { keys: ['MENU', '2', 'F5', 'F1', 'F2'], fields: ['Lower', 'Upper', 'σ', 'μ'] },
  'Inverse Normal': { keys: ['MENU', '2', 'F5', 'F1', 'F3'], fields: ['Tail', 'Area', 'σ', 'μ'] }
};
const bound = v => String(v).includes('10⁹⁹') ? (String(v).startsWith('−') ? -Infinity : Infinity) : Number(v);
function independent(name, fields) {
  const f = Object.fromEntries(fields.map(([k, v]) => [k.replace(/^First (calculation|cutoff): /, ''), v]));
  if (name === 'Binomial PD') return binom(Number(f.Numtrial), Number(f.p), Number(f.x), Number(f.x));
  if (name === 'Binomial CD') return binom(Number(f.Numtrial), Number(f.p), Number(f.Lower), Number(f.Upper));
  if (name === 'Normal CD') { const z = v => (bound(v) - Number(f.μ)) / Number(f.σ); const P = v => (v === Infinity ? 1 : v === -Infinity ? 0 : Phi(v)); return P(z(f.Upper)) - P(z(f.Lower)); }
  if (name === 'Inverse Normal') return Number(f.μ) + Number(f.σ) * invPhi(f.Tail === 'Left' ? Number(f.Area) : 1 - Number(f.Area));
  throw new Error(`no independent model for ${name}`);
}

const failures = [];
let screens = 0, guides = 0, reasons = 0, deferred = 0;
const manifest = JSON.parse(readFileSync('src/content/ap-statistics/course.json', 'utf8'));
for (const { id: unit } of manifest.units) {
  for (const question of JSON.parse(readFileSync(`src/content/ap-statistics/units/${unit}.json`, 'utf8')).questions) {
    const id = `${unit}:${question.id}`;
    const calc = question.calculator || {};
    if (calc.status === 'deferred') {
      if (calc.needed || calc.steps || calc.distribution || !calc.reason) failures.push(`${id}: deferred calculator support must have a reason and no guide`);
      deferred += 1;
      continue;
    }
    if (!calc.needed && !calc.distribution) {
      if (!calc.reason || calc.reason.length < 20) failures.push(`${id}: no calculator guide and no reason given`);
      reasons += 1;
      continue;
    }
    if (calc.distribution) {
      const route = routes[calc.distribution.name];
      if (!route) { failures.push(`${id}: unknown distribution ${calc.distribution.name}`); continue; }
      const fieldNames = calc.distribution.fields.map(([k]) => k.replace(/^First (calculation|cutoff): /, ''));
      if (JSON.stringify(fieldNames) !== JSON.stringify(route.fields)) failures.push(`${id}: field order ${fieldNames} differs from the Skill Finder card`);
      const guide = prepareGuide(question);
      const opening = guide.steps.slice(0, 5).map(step => step.keys[0]);
      if (JSON.stringify(opening) !== JSON.stringify(route.keys)) failures.push(`${id}: menu route ${opening} differs from the Skill Finder card`);
      const result = guide.steps.find(step => step.frame?.type === 'result').frame.value;
      const target = independent(calc.distribution.name, calc.distribution.fields);
      if (Math.abs(result - target) > 1e-7 * Math.max(1, Math.abs(target))) failures.push(`${id}: calculator result ${result} vs independent ${target}`);
      for (const step of guide.steps) if (!step.keys?.length || !step.note) failures.push(`${id}: step "${step.title}" lacks keys or a note`);
      guides += 1;
      continue;
    }
    for (const step of calc.steps || []) {
      if (step.mode !== 'result') continue;
      screens += 1;
      const exact = evaluate(step.input);
      const shown = Number(String(step.result).replace('−', '-'));
      if (Math.abs(shown - exact) > 1e-9 * Math.max(1, Math.abs(exact))) failures.push(`${id}: ${step.input} shows ${step.result}, exact ${exact}`);
      if (significant(String(step.result)) > 10) failures.push(`${id}: ${step.result} shows more than 10 significant digits`);
      if (step.exact && isExact(exact) && !exact.eq(evaluate(step.exact))) failures.push(`${id}: exact ${step.exact} disagrees with ${step.input}`);
      if (JSON.stringify(step.keys) !== JSON.stringify(spell(step.input))) failures.push(`${id}: keys ${step.keys.join(' ')} do not spell ${step.input}`);
    }
  }
}
if (failures.length) { console.error(`Calculator check failed:\n- ${failures.join('\n- ')}`); process.exitCode = 1; }
else console.log(`Verified ${screens} arithmetic screens, ${guides} distribution walkthroughs, and ${reasons} reasoning-only explanations; ${deferred} calculator guides deferred (tool check; no physical fx-CG50 verification recorded).`);
